const [checkedLayout, command] = await Promise.allSettled([
  layout.verifyLayout(),
  native.openCommand()
]);
if (checkedLayout.status === "rejected") {
  if (command.status === "rejected") throw new AggregateError([checkedLayout.reason, command.reason], "Pi layout and snapshot admission failed");
  if (command.status === "fulfilled") {
    try {
      await command.value.close();
    } catch (cleanupError) {
      throw new AggregateError([checkedLayout.reason, cleanupError], "Pi layout admission and unpublished command cleanup failed");
    }
  }
  throw checkedLayout.reason;
}
if (command.status === "rejected") throw command.reason;
return command.value;
